import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("Not Found")
        return

    idx = 0
    n = int(data[idx])
    idx += 1

    nodes = []
    for _ in range(n):
        val = int(data[idx])
        left = int(data[idx + 1])
        right = int(data[idx + 2])
        nodes.append((val, left, right))
        idx += 3

    k = int(data[idx])

    if n == 0:
        print("Not Found")
        return

    # Build adjacency info: value -> (left_child, right_child)
    children = {}
    for val, left, right in nodes:
        children[val] = (left, right)

    # Find root: node that is not a child of any other node
    all_children = set()
    for val, left, right in nodes:
        if left != -1:
            all_children.add(left)
        if right != -1:
            all_children.add(right)

    root = None
    for val, _, _ in nodes:
        if val not in all_children:
            root = val
            break

    # Search using stack (iterative DFS)
    if root is None:
        print("Not Found")
        return

    stack = [root]
    while stack:
        current = stack.pop()
        if current == k:
            print("Found")
            return
        if current in children:
            left, right = children[current]
            if right != -1:
                stack.append(right)
            if left != -1:
                stack.append(left)

    print("Not Found")

if __name__ == "__main__":
    main()
